class BattleBot(BotAI):
    """
    Terran Auto-Micro Bot - Optimized Version
    Strategy: Immediate Stimpack + Focus Fire Nearest Enemy + Simple Kiting + Medivac Healing
    """

    def __init__(self):
        super().__init__()
        self.stim_used = set()
        self.started = False

    async def on_step(self, iteration: int):
        # Get units
        marines = self.units(UnitTypeId.MARINE)
        marauders = self.units(UnitTypeId.MARAUDER)
        medivacs = self.units(UnitTypeId.MEDIVAC)
        ghosts = self.units(UnitTypeId.GHOST)
        tanks = self.units(UnitTypeId.SIEGETANK) | self.units(UnitTypeId.SIEGETANKSIEGED)

        bio_units = marines | marauders
        all_combat = bio_units | ghosts | tanks
        enemies = self.enemy_units
        enemy_pos = Point2((27, 27))

        if not all_combat.exists:
            return

        # No enemies - quick attack
        if not enemies.exists:
            for unit in all_combat:
                unit.attack(enemy_pos)
            for medivac in medivacs:
                medivac.move(enemy_pos)
            return

        # === Optimization 1: Stimpack immediately upon first enemy sight ===
        if not self.started:
            self.started = True
            for unit in bio_units:
                if unit.health > 20:
                    if unit.type_id == UnitTypeId.MARINE:
                        unit(AbilityId.EFFECT_STIM_MARINE)
                    elif unit.type_id == UnitTypeId.MARAUDER:
                        unit(AbilityId.EFFECT_STIM_MARAUDER)
                    self.stim_used.add(unit.tag)

        # === Optimization 2: Simplified target selection ===
        low_health = enemies.filter(lambda u: u.health_percentage < 0.4)
        if low_health.exists:
            target = low_health.closest_to(bio_units.center)
        else:
            target = enemies.closest_to(bio_units.center)

        # === Optimization 3: Kiting tactics ===
        for unit in bio_units:
            closest = enemies.closest_to(unit.position)
            dist = unit.distance_to(closest)
            # Maintain distance from melee units
            if closest.type_id in [UnitTypeId.ZEALOT, UnitTypeId.ZERGLING]:
                if dist < 3:
                    retreat_pos = unit.position.towards(closest.position, -4)
                    unit.move(retreat_pos)
                    continue
            unit.attack(target)

        # === Ghost EMP ===
        for ghost in ghosts:
            shielded = enemies.filter(lambda u: u.shield > 20)
            if shielded.exists and ghost.energy >= 75:
                emp_target = max(shielded, key=lambda u: enemies.closer_than(3, u).amount)
                ghost(AbilityId.EMP_EMP, emp_target.position)
            else:
                ghost.attack(target)

        # === Tank Control ===
        for tank in tanks:
            if tank.type_id == UnitTypeId.SIEGETANK:
                closest = enemies.closest_to(tank.position)
                dist = tank.distance_to(closest)
                if 3 < dist < 13:
                    tank(AbilityId.SIEGEMODE_SIEGEMODE)
                else:
                    tank.attack(target)
            else:  # SIEGETANKSIEGED
                if tank.distance_to(enemies.closest_to(tank)) < 3:
                    tank(AbilityId.UNSIEGE_UNSIEGE)
                else:
                    tank.attack(target)

        # === Medivac Healing ===
        for medivac in medivacs:
            if bio_units.exists:
                injured = bio_units.filter(lambda u: u.health_percentage < 0.8)
                if injured.exists:
                    heal_target = min(injured, key=lambda u: u.health)
                    medivac(AbilityId.MEDIVACHEAL_HEAL, heal_target)
                else:
                    medivac.move(bio_units.center)
